170→            current: "0.1.0".to_string(),
171→            latest: "0.2.0".to_string(),
172→            update_available: true,
173→            release_url: None,
174→            checked_at: Utc::now(),
175→        };
176→        let method = InstallMethod::Manual {
177→            path: PathBuf::from("/tmp/bivvy"),
178→        };
179→
180→        let result = prompt_for_update(&mut ui, &info, &method).unwrap();
181→        assert!(!result);
