202→
203→    #[test]
204→    fn prompt_for_update_with_cargo() {
205→        let mut ui = MockUI::new();
206→        // Set response for the confirm prompt
207→        ui.set_prompt_response("update_bivvy", "false");
208→
209→        let info = UpdateInfo {
210→            current: "0.1.0".to_string(),
211→            latest: "0.2.0".to_string(),
212→            update_available: true,
213→            release_url: None,
214→            checked_at: Utc::now(),
215→        };
216→        let method = InstallMethod::Cargo;
217→
218→        // This will prompt but MockUI returns String, not Bool
219→        let result = prompt_for_update(&mut ui, &info, &method).unwrap();
220→        // MockUI returns PromptResult::String, not Bool, so this is Ok(false)
221→        assert!(!result);
222→    }
223→
224→    #[test]
225→    fn show_update_notification_with_ui() {
226→        let mut ui = MockUI::new();
227→        // This will check for updates which may or may not find anything
228→        // Mostly testing that it doesn't panic
229→        show_update_notification(&mut ui);
230→    }
231→
232→    #[test]
233→    fn suppress_and_check_notification() {
234→        // Test the flow: suppress then check
235→        suppress_notification();
236→        assert!(is_notification_suppressed());
237→        // Note: we don't clear env vars because tests run in parallel
238→        // and other tests may depend on this state
239→    }
240→}
